def load_effects(line, panel, anchor=None):
    """z (P x G) against the pool, plus per-cell control-pool matrix on the panel for halvings."""
    pb = np.load(ROOT / "data" / "pb" / f"{line}.npz", allow_pickle=True)
    gpos = {g: j for j, g in enumerate(pb["genes"])}
    cols = [gpos[g] for g in panel]
    targets = list(pb["targets"])
    pm = pb["pert_mean"][:, cols]
    if anchor is not None:
        ti = [targets.index(t) for t in anchor]; pm = pm[ti]; targets = list(anchor)
    Z = pm - pb["pool_mean"][cols]

def crossline(G, sym_anchor, size=2000):
    out = []
    for name, sub in (("2,317 Ensembl anchor", None), ("paper-matched symbol anchor", sym_anchor)):
        D = G if sub is None else G[G.target_ens.isin(sub)]
        for q in ("a", "m", "s"):
            M = D.pivot(index="target_ens", columns="line", values=f"{q}_{size}")[LINES].dropna()
            pairs = [(x, y, pearsonr(M[x], M[y])[0]) for i, x in enumerate(LINES) for y in LINES[i + 1:]]
            out.append({"anchor": name, "n_perturbations": len(M), "panel": size, "quantity": q,
                        "kendalls_W": kendalls_w(M.to_numpy()), "mean_pairwise_pearson": np.mean([r for *_, r in pairs]),
                        "min_pair_r": min(r for *_, r in pairs), "all_positive": all(r > 0 for *_, r in pairs),
                        **{f"r_{x}_{y}": r for x, y, r in pairs}})
    return pd.DataFrame(out)

def shared(key, min_cells=2, pc_only=False):
    sets = []
    for l in lines:
        d = T[(T.line == l) & (T.n >= min_cells)]
        if pc_only:
            d = d[d.protein_coding]
        sets.append(set(d[key].dropna()))
    return set.intersection(*sets)

def donor_components(Zs, names):
    betas, resid = {}, {}
    for Z in Zs:
        b, r = decompose(Z, shared_axis(Z))
        for i, p in enumerate(names):
            betas.setdefault(p, []).append(b[i]); resid.setdefault(p, []).append(r[i])
    return {p: float(np.mean(v)) for p, v in betas.items()}, {p: np.mean(v, 0) for p, v in resid.items()}

