def hyper(sel, background, sets, min_size=5):
    sel = set(sel) & background; out = []
    for term, members in sets.items():
        m = members & background
        if len(m) < min_size:
            continue
        k = len(sel & m)
        if k == 0:
            continue
        p = hypergeom.sf(k - 1, len(background), len(m), len(sel))
        out.append((term, k, len(m), p, ",".join(sorted(sel & m)[:8])))
    df = pd.DataFrame(out, columns=["term", "hits", "set_size", "p", "genes"])
    if len(df):
        df["q"] = multipletests(df.p, method="fdr_bh")[1]
    return df.sort_values("p") if len(df) else df

