def plate5():
    out = {}
    St = pd.read_csv(RES / "stress_per_line.tsv", sep="\t")
    A = St[St.condition == "A:independent halves"].groupby("line").control_noise_norm.mean()
    ratios, cells = [], []
    for l in LINES:
        D = dec(l); ratios.extend(np.linalg.norm(D["Z"], axis=1) / A[l])
        o = pd.read_parquet(ROOT / "data" / "mat" / l / "obs_main.parquet"); cells.extend(o[~o.is_control].groupby("target_ens").size().to_numpy())
    out["crispr"] = {"ratio": r3(np.log10(ratios)), "cells": [int(x) for x in cells]}
    for ds in ("tahoe", "chemfish"):
        b = pd.read_csv(RES / f"{ds}_betas.tsv", sep="\t")
        out[ds] = {"ratio": r3(np.log10(b.norm / b.noise_norm))}
    tc = pd.read_csv(RES / "tahoe_cells_per_condition.tsv", sep="\t"); out["tahoe"]["cells"] = [int(x) for x in tc.n.sample(20000, random_state=SEED)]
    P = pd.read_csv(RES / "chemfish_axis_per_context.tsv", sep="\t"); out["chemfish"]["median_cells_by_tissue"] = r3(P.median_cells)
    return out

def grid(draws=30):
    ref = {l: st.ref(l) for l in LINES}
    Zs = {(l, k): np.load(OUT / f"{l}_k{k}.npy") for l in LINES for k in KS}
    P = len(ref["K562"]["names"]); rows = []
    for n in NS:
        for d in range(draws if n < P else 1):
            S = np.sort(np.random.default_rng(SEED + 97 * d + n).permutation(P)[:n])
            for k in KS:
                beta, fid, cu = {}, [], []
                for l in LINES:
                    Z = Zs[(l, k)][S]; u = shared_axis(Z); b = Z @ u
                    beta[l] = b; fid.append(np.corrcoef(b, ref[l]["beta"][S])[0, 1]); cu.append(float(u @ ref[l]["u"]))
                row = {"n": n, "k": k if k else "all", "draw": d, "fidelity_beta_r": float(np.median(fid)), "fidelity_cos_u": float(np.median(cu))}
                for g, ls in GROUPS.items():
                    row[f"conservation_{g}"] = float(np.mean([np.corrcoef(beta[a], beta[b])[0, 1] for a, b in combinations(ls, 2)]))
                rows.append(row)
        print(f"n={n} done", flush=True)
    T = pd.DataFrame(rows); T.to_csv(ROOT / "results" / "phase_grid.tsv", sep="\t", index=False)
    Sm = T.groupby(["n", "k"], sort=False).agg(**{c: (c, "median") for c in T.columns if c not in ("n", "k", "draw")},
                                               cons_RN_p10=("conservation_Replogle/Nadig", lambda x: float(np.percentile(x, 10)))).reset_index()
    Sm.to_csv(ROOT / "results" / "phase_summary.tsv", sep="\t", index=False)
    print(Sm.pivot(index="n", columns="k", values="conservation_Replogle/Nadig").round(2).to_string())

