def effects(ds, design, panel, min_cells):
    d, A, B, cA, cB, groups = load(ds)
    gi = {g: i for i, g in enumerate(groups)}
    A = np.asarray(A[:, panel]); B = np.asarray(B[:, panel])
    rec = {}
    for i, ctx, pert, is_c, ctrls in design:
        if is_c:
            continue
        ci = [gi[c] for c in ctrls if c in gi]
        if not ci or cA[i] < min_cells or cB[i] < min_cells:
            continue
        nA, nB = cA[ci].sum(), cB[ci].sum()
        if nA < min_cells or nB < min_cells:
            continue
        ctlA, ctlB = A[ci].sum(0) / nA, B[ci].sum(0) / nB
        zA, zB = A[i] / cA[i] - ctlA, B[i] / cB[i] - ctlB
        z = (A[i] + B[i]) / (cA[i] + cB[i]) - (A[ci].sum(0) + B[ci].sum(0)) / (nA + nB)
        noise = ctlA - ctlB
        rec.setdefault(ctx, {})[pert] = (z, zA, zB, cA[i] + cB[i], noise)
    return rec

def build_rec(S, n, drug_wells, ctrl_of, name_of, clus):
    rec = {}
    for c, cname in enumerate(clus):
        for w in drug_wells:
            if n[w, c, 0] < MIN_HALF or n[w, c, 1] < MIN_HALF:
                continue
            cw = ctrl_of[w]
            cA, nA = mean(S, n, cw, c, 0)
            cB, nB = mean(S, n, cw, c, 1)
            if nA < MIN_HALF or nB < MIN_HALF:
                continue
            zA, zB = S[w, c, 0] / n[w, c, 0] - cA, S[w, c, 1] / n[w, c, 1] - cB
            z = S[w, c].sum(0) / n[w, c].sum() - mean(S, n, cw, c)[0]
            rec.setdefault(cname, {})[name_of[w]] = (z, zA, zB, int(n[w, c].sum()), cA - cB)
    return rec

